#!/bin/bash
# Generated by tools/aether_train_run.py for run qwen38-27b-toon; do not edit by hand.
# Waits until the base weights are complete, the host has 60 GB available
# and no other aether-train/aether-serve container runs, then starts train.sh once.
set -u
R=$HOME/aether-train/qwen38-27b-toon
LOG="$R/logs/when_ready.log"
mkdir -p "$R/logs"
log() { echo "[$(date -u +%Y-%m-%dT%H:%M:%SZ)] $*" >> "$LOG"; }
log "waiting for weights, memory and a free GPU"
while true; do
  MODEL=$(python3 -c 'import glob, json, os, sys
p = sys.argv[1]
if not os.path.isfile(p + '"'"'/config.json'"'"'):
    print('"'"'model=missing'"'"'); sys.exit()
idx = p + '"'"'/model.safetensors.index.json'"'"'
files = set(json.load(open(idx))['"'"'weight_map'"'"'].values()) if os.path.isfile(idx) else {os.path.basename(f) for f in glob.glob(p + '"'"'/*.safetensors'"'"')}
missing = [f for f in files if not os.path.isfile(p + '"'"'/'"'"' + f) or os.path.getsize(p + '"'"'/'"'"' + f) == 0]
busy = glob.glob(p + '"'"'/.cache/huggingface/download/*.incomplete'"'"')
print('"'"'model=ok'"'"' if files and not missing and not busy else '"'"'model=partial'"'"')
' /storage/models/Qwen3.8-27B)
  AVAIL=$(free -g | awk '/^Mem:/{print $7}')
  OTHERS=$(docker ps --format '{{.Names}}' | grep -E '^aether-(train|serve)-' | grep -v '^aether-train-qwen38-27b-toon$' | tr '
' ' ')
  if [ "$MODEL" = model=ok ] && [ "$AVAIL" -ge 60 ] && [ -z "$OTHERS" ]; then
    log "ready ($MODEL, $AVAIL GB available); starting training"
    bash "$R/train.sh" >> "$LOG" 2>&1
    log "train.sh exit $?"
    exit 0
  fi
  log "not yet: $MODEL, $AVAIL GB available, others: ${OTHERS:-none}"
  sleep 300
done
